import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Grid,
  Alert,
  Accordion,
  AccordionSummary,
  AccordionDetails
} from '@mui/material';
import {
  ExpandMore,
  Lightbulb,
  AccountBalance
} from '@mui/icons-material';

import { FundingParams, StrategyType, CalculationResult } from '../../types';
import { FundingCalculator } from '../../services/calculators/FundingCalculator';
import { dataAccessLayer } from '../../services/database';
import { OverviewCards } from '../shared/OverviewCards';
import { PnLAnalysis } from '../shared/PnLAnalysis';
import { FundingParameters } from './components/FundingParameters';
import { FundingStatus } from './components/FundingStatus';
import { FundingResultTable } from './components/FundingResultTable';

export const FundingPage: React.FC = () => {
  const [params, setParams] = useState<Partial<FundingParams>>({
    name: '资金费率反向策略',
    type: StrategyType.FUNDING,
    fundingThreshold: -0.001, // -0.1%
    leverageRatio: 5,
    maxLevels: 8,
    totalCapital: 10000,
    isLong: true,
    isAddPosition: false,
    existingPosition: {
      holdings: 0,
      averageCost: 0,
      totalInvested: 0
    }
  });

  const [currentPrice, setCurrentPrice] = useState<number>(50000);
  const [currentFundingRate, setCurrentFundingRate] = useState<number>(-0.0015); // -0.15%
  const [useCurrentPrice, setUseCurrentPrice] = useState<boolean>(true);
  const [result, setResult] = useState<CalculationResult | null>(null);
  const [status, setStatus] = useState<any>(null);
  const [fundingReturn, setFundingReturn] = useState<any>(null);
  const [errors, setErrors] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [saved, setSaved] = useState<boolean>(false);

  // 实时计算
  useEffect(() => {
    if (params.fundingThreshold !== undefined && params.leverageRatio && 
        params.maxLevels && params.totalCapital && params.isLong !== undefined) {

      const validation = FundingCalculator.validateParams(params);
      setErrors(validation.errors);

      if (validation.valid) {
        try {
          const fullParams: FundingParams = {
            id: `funding_${Date.now()}`,
            name: params.name || '资金费率反向策略',
            type: StrategyType.FUNDING,
            createdAt: new Date(),
            updatedAt: new Date(),
            fundingThreshold: params.fundingThreshold,
            leverageRatio: params.leverageRatio,
            maxLevels: params.maxLevels,
            totalCapital: params.totalCapital,
            isLong: params.isLong,
            isAddPosition: params.isAddPosition,
            existingPosition: params.existingPosition
          };

          const calcResult = FundingCalculator.calculate(
            fullParams, 
            useCurrentPrice ? currentPrice : undefined,
            currentFundingRate
          );
          setResult(calcResult);

          // 计算策略状态
          const strategyStatus = FundingCalculator.getStrategyStatus(fullParams, currentFundingRate);
          setStatus(strategyStatus);

          // 计算收益预期
          const returnExpectation = FundingCalculator.calculateFundingReturn(
            fullParams, 
            currentFundingRate, 
            1
          );
          setFundingReturn(returnExpectation);

        } catch (error) {
          console.error('计算错误:', error);
          setResult(null);
          setStatus(null);
          setFundingReturn(null);
        }
      } else {
        setResult(null);
        setStatus(null);
        setFundingReturn(null);
      }
    }
  }, [params, currentPrice, currentFundingRate, useCurrentPrice]);

  const handleParamChange = (field: keyof FundingParams, value: any) => {
    setParams(prev => ({ ...prev, [field]: value }));
    setSaved(false);
  };

  const handleSave = async () => {
    if (!result) return;

    setLoading(true);
    try {
      const fullParams: FundingParams = {
        id: `funding_${Date.now()}`,
        name: params.name || '资金费率反向策略',
        type: StrategyType.FUNDING,
        createdAt: new Date(),
        updatedAt: new Date(),
        fundingThreshold: params.fundingThreshold!,
        leverageRatio: params.leverageRatio!,
        maxLevels: params.maxLevels!,
        totalCapital: params.totalCapital!,
        isLong: params.isLong!,
        isAddPosition: params.isAddPosition,
        existingPosition: params.existingPosition
      };

      await dataAccessLayer.saveStrategy(fullParams);
      await dataAccessLayer.saveCalculation(result);
      setSaved(true);

      setTimeout(() => setSaved(false), 3000);
    } catch (error) {
      console.error('保存失败:', error);
    } finally {
      setLoading(false);
    }
  };

  // 生成建议
  const recommendations = params.fundingThreshold !== undefined && params.leverageRatio && 
    params.maxLevels && params.totalCapital && params.isLong !== undefined ?
    FundingCalculator.generateRecommendations(params as FundingParams, currentFundingRate) : [];

  return (
    <Box sx={{ p: { xs: 1, sm: 2 }, width: '100%', maxWidth: '100%' }}>
      <Typography variant="h4" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
        <AccountBalance color="primary" />
        资金费率反向策略
      </Typography>

      <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
        利用资金费率收益，在负费率时做多收取费用，在正费率时做空收取费用，同时通过分档降低价格风险。
      </Typography>

      <Grid container spacing={2}>
        {/* 参数设置 */}
        <Grid item xs={12} lg={4}>
          <FundingParameters
            params={params}
            currentPrice={currentPrice}
            currentFundingRate={currentFundingRate}
            useCurrentPrice={useCurrentPrice}
            onParamChange={handleParamChange}
            onCurrentPriceChange={setCurrentPrice}
            onCurrentFundingRateChange={setCurrentFundingRate}
            onUseCurrentPriceChange={setUseCurrentPrice}
            onSave={handleSave}
            canSave={!!result}
            loading={loading}
            saved={saved}
          />
        </Grid>

        {/* 计算结果 */}
        <Grid item xs={12} lg={8}>
          {errors.length > 0 && (
            <Alert severity="error" sx={{ mb: 2 }}>
              <ul style={{ margin: 0, paddingLeft: 20 }}>
                {errors.map((error, index) => (
                  <li key={index}>{error}</li>
                ))}
              </ul>
            </Alert>
          )}

          {/* 策略状态 */}
          {status && fundingReturn && (
            <FundingStatus
              status={status}
              fundingReturn={fundingReturn}
              currentFundingRate={currentFundingRate}
            />
          )}

          {/* 策略建议 */}
          {recommendations.length > 0 && (
            <Accordion sx={{ mb: 2 }}>
              <AccordionSummary expandIcon={<ExpandMore />}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                  <Lightbulb />
                  <Typography variant="h6">策略建议</Typography>
                </Box>
              </AccordionSummary>
              <AccordionDetails>
                {recommendations.map((rec: string, index: number) => (
                  <Typography key={index} variant="body2" sx={{ mb: 1 }}>
                    {rec}
                  </Typography>
                ))}
              </AccordionDetails>
            </Accordion>
          )}

          {result && (
            <>
              {/* 概览卡片 */}
              <OverviewCards result={result} />

              {/* 盈亏分析 */}
              {useCurrentPrice && result.currentPriceAnalysis?.unrealizedPnL !== undefined && (
                <PnLAnalysis result={result} />
              )}

              {/* 详细档位表格 */}
              <FundingResultTable result={result} />
            </>
          )}
        </Grid>
      </Grid>
    </Box>
  );
};
